solution.solution.cpp:
#include <iostream>
#include <limits>

int readInt()
{
    while (true)
    {
        int value{};
        std::cin >> value;
        if (std::cin)
        {
            return value;
        }
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    }
}

unitTests:
TEST("a number first time") { int v{}; xenon::run_with_input("42
", [&] { v = readInt(); }); CHECK_EQ(v, 42); }
TEST("skips one bad line") { int v{}; xenon::run_with_input("abc
12
", [&] { v = readInt(); }); CHECK_EQ(v, 12); }
TEST("skips several bad lines") { int v{}; xenon::run_with_input("hello
x9
?
-7
", [&] { v = readInt(); }); CHECK_EQ(v, -7); }

